export class HierarchicalOrchestrator {
  constructor(agents) {
    this.agents = agents;
    this.taskQueue = [];
  }

  allocateTask(task) {
    const availableAgent = this.agents.find(agent => agent.isAvailable());
    if (availableAgent) {
      availableAgent.assignTask(task);
    } else {
      this.taskQueue.push(task);
    }
  }

  processQueue() {
    while (this.taskQueue.length > 0) {
      const task = this.taskQueue.shift();
      this.allocateTask(task);
    }
  }

  dynamicReallocation() {
    this.agents.forEach(agent => {
      if (agent.isIdle() && this.taskQueue.length > 0) {
        const task = this.taskQueue.shift();
        agent.assignTask(task);
      }
    });
  }
}